<?php
namespace App\Services;
use ZipArchive;
class XlsxService {
 public function write(array $headers,array $rows,string $path): void { $zip=new ZipArchive(); if($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new \RuntimeException('Unable to create XLSX.'); $strings=[];$idx=[];$get=function($v)use(&$strings,&$idx){$v=(string)$v;if(!isset($idx[$v])){$idx[$v]=count($strings);$strings[]=$v;}return $idx[$v];}; $all=array_merge([$headers],$rows);$sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';foreach($all as $ri=>$row){$sheet.='<row r="'.($ri+1).'">';foreach(array_values($row) as $ci=>$v){$col=$this->col($ci+1);$sheet.='<c r="'.$col.($ri+1).'" t="s"><v>'.$get($v).'</v></c>';}$sheet.='</row>';}$sheet.='</sheetData></worksheet>';$sst='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="'.count($strings).'" uniqueCount="'.count($strings).'">';foreach($strings as $s)$sst.='<si><t>'.htmlspecialchars($s,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></si>';$sst.='</sst>';$zip->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/></Types>');$zip->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$zip->addFromString('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Report" sheetId="1" r:id="rId1"/></sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/></Relationships>');$zip->addFromString('xl/worksheets/sheet1.xml',$sheet);$zip->addFromString('xl/sharedStrings.xml',$sst);$zip->close(); }
 public function read(string $path,int $maxRows=5000,int $maxCols=50,int $maxUncompressed=20_000_000): array { $zip=new ZipArchive();if($zip->open($path)!==true)throw new \RuntimeException('Invalid XLSX archive.');$sum=0;for($i=0;$i<$zip->numFiles;$i++){$st=$zip->statIndex($i);$sum+=(int)($st['size']??0);if($sum>$maxUncompressed)throw new \RuntimeException('XLSX decompressed content exceeds safety limit.');} $strings=[];$sst=$zip->getFromName('xl/sharedStrings.xml');if($sst!==false){$xml=simplexml_load_string($sst);foreach($xml->si??[] as $si)$strings[]=(string)($si->t??$si->r->t??'');if(count($strings)>100000)throw new \RuntimeException('XLSX shared-string limit exceeded.');} $sheet=$zip->getFromName('xl/worksheets/sheet1.xml');$zip->close();if($sheet===false)throw new \RuntimeException('XLSX sheet not found.');$xml=simplexml_load_string($sheet);$out=[];foreach($xml->sheetData->row??[] as $row){if(count($out)>=$maxRows)throw new \RuntimeException('XLSX row limit exceeded.');$vals=[];foreach($row->c??[] as $cell){if(count($vals)>=$maxCols)throw new \RuntimeException('XLSX column limit exceeded.');$v=(string)$cell->v;$vals[]=(string)($cell['t']==='s'?($strings[(int)$v]??''):$v);} $out[]=$vals;}return $out; }
 private function col(int $n): string{$s='';while($n>0){$n--;$s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;}
}
